class Solution:
    def seePeople(self, heights):
        m, n = len(heights), len(heights[0])
        ans = [[0] * n for _ in range(m)]
        for i in range(m):
            st = []
            for j in range(n):
                cnt = 0
                while st and heights[i][st[-1]] < heights[i][j]:
                    st.pop(); cnt += 1
                if st:
                    cnt += 1
                ans[i][j] += cnt
                while st and heights[i][st[-1]] == heights[i][j]:
                    st.pop()
                st.append(j)
        for j in range(n):
            st = []
            for i in range(m):
                cnt = 0
                while st and heights[st[-1]][j] < heights[i][j]:
                    st.pop(); cnt += 1
                if st:
                    cnt += 1
                ans[i][j] += cnt
                while st and heights[st[-1]][j] == heights[i][j]:
                    st.pop()
                st.append(i)
        return ans

