class Solution {
public:
    vector<vector<int>> seePeople(vector<vector<int>>& h) {
        int m = h.size(), n = h[0].size();
        vector<vector<int>> ans(m, vector<int>(n, 0));
        for (int i = 0; i < m; i++) {
            vector<int> st;
            for (int j = 0; j < n; j++) {
                int cnt = 0;
                while (!st.empty() && h[i][st.back()] < h[i][j]) { st.pop_back(); cnt++; }
                if (!st.empty()) cnt++;
                ans[i][j] += cnt;
                while (!st.empty() && h[i][st.back()] == h[i][j]) st.pop_back();
                st.push_back(j);
            }
        }
        for (int j = 0; j < n; j++) {
            vector<int> st;
            for (int i = 0; i < m; i++) {
                int cnt = 0;
                while (!st.empty() && h[st.back()][j] < h[i][j]) { st.pop_back(); cnt++; }
                if (!st.empty()) cnt++;
                ans[i][j] += cnt;
                while (!st.empty() && h[st.back()][j] == h[i][j]) st.pop_back();
                st.push_back(i);
            }
        }
        return ans;
    }
};

