class Solution {
    public int[][] seePeople(int[][] h) {
        int m = h.length, n = h[0].length;
        int[][] ans = new int[m][n];
        Deque<Integer> st = new ArrayDeque<>();
        for (int i = 0; i < m; i++) {
            st.clear();
            for (int j = 0; j < n; j++) {
                int cnt = 0;
                while (!st.isEmpty() && h[i][st.peek()] < h[i][j]) { st.pop(); cnt++; }
                if (!st.isEmpty()) cnt++;
                ans[i][j] += cnt;
                while (!st.isEmpty() && h[i][st.peek()] == h[i][j]) st.pop();
                st.push(j);
            }
        }
        for (int j = 0; j < n; j++) {
            st.clear();
            for (int i = 0; i < m; i++) {
                int cnt = 0;
                while (!st.isEmpty() && h[st.peek()][j] < h[i][j]) { st.pop(); cnt++; }
                if (!st.isEmpty()) cnt++;
                ans[i][j] += cnt;
                while (!st.isEmpty() && h[st.peek()][j] == h[i][j]) st.pop();
                st.push(i);
            }
        }
        return ans;
    }
}

